for(const [key,label] of Object.entries(sceneCatalog).map(([key,entry])=>[key,entry.label])){const b=document.createElement('button');b.dataset.scene=key;b.innerHTML='<span class="scene-icon" aria-hidden="true">'+(sceneIcons[key]||sceneIcons.forest)+'</span>'+label;b.onclick=()=>setScene(key);$('sceneOptions').append(b)}
for(const [key,label] of [['clear','無'],['rain','雨'],['snow','雪'],['typhoon','颱風'],['tornado','龍捲風'],['thunder','雷電']]){const b=document.createElement('button');b.dataset.weather=key;b.innerHTML='<span class="weather-icon" aria-hidden="true">'+weatherIcons[key]+'</span><span>'+label+'</span>';b.onclick=()=>{state.effect=key;render()};$('weatherOptions').append(b)}
$('background').addEventListener('input',()=>{state.lockScene=true;syncHifi();persistSettings()});
$('pauseWeather').onclick=()=>{state.paused=!state.paused;render()};
$('lockScene').onchange=()=>{state.lockScene=$('lockScene').checked;persistSettings()};
$('openPrompt').onclick=()=>{$('promptBox').scrollIntoView({behavior:'instant',block:'center'});$('prompt').focus()};
function openComponent(target){$('componentDetails').open=true;$(target).focus()}
$('positionTool').onclick=()=>{if(state.layout==='A'){editingPositions=!editingPositions;$('editPositions').checked=editingPositions;syncPositions();$('positionTool').setAttribute('aria-pressed',String(editingPositions))}else openComponent('editPositions')};
$('sizeTool').onclick=()=>openComponent('clockSize');$('visibilityTool').onclick=()=>openComponent('clockVisible');
