const c=$('weather'),ctx=c.getContext('2d');let frames=0;function draw(t){const w=c.clientWidth,h=c.clientHeight;if(c.width!==Math.floor(w)||c.height!==Math.floor(h)){c.width=w;c.height=h}ctx.clearRect(0,0,w,h);const f=state.effect;$('flash').style.opacity='0';if(f==='clear'||state.intensity===0)return;const tm=state.reduced||state.paused?0:t/1000;ctx.lineWidth=1;ctx.strokeStyle='rgba(212,232,228,.42)';ctx.fillStyle='rgba(237,244,240,.72)';if(['rain','typhoon','thunder','snow'].includes(f)){const count=Math.round((state.reduced?35:f==='typhoon'?170:90)*state.intensity/55);for(let i=0;i<count;i++){let x=(i*97+tm*(f==='typhoon'?170:20))%w,y=(i*61+tm*(f==='snow'?23:180))%h;if(f==='snow'){ctx.beginPath();ctx.arc(x,y,1+i%3,0,7);ctx.fill()}else{ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(f==='typhoon'?25:5),y+15);ctx.stroke()}}}if(f==='tornado'){for(let i=0;i<Math.round(40*state.intensity/100);i++){const y=h*.25+i*h*.014;ctx.beginPath();ctx.ellipse(w*.37+Math.sin(i*.2+tm)*12,y,(40-i)*2.5+4,6,0,0,7);ctx.stroke()}}if(!state.reduced&&!state.paused&&state.lightning&&['thunder','typhoon'].includes(f)){const phase=t%9000;$('flash').style.opacity=phase<250?String(.1*Math.sin(phase/250*Math.PI)):'0'}else $('flash').style.opacity='0'}function animate(t){frames++;if(frames%2===0&&!state.reduced&&!state.paused)draw(t);requestAnimationFrame(animate)}addEventListener('resize',()=>{$('time').style.fontSize='clamp(25px,'+((matchMedia('(max-width:600px)').matches?18:7.2)*state.clockSize/100)+'vw,'+(120*state.clockSize/100)+'px)';renderLayout();if(state.layout==='A'){const k=positionKeys();if(state.clockVisible)clampPosition('clock',state[k.x],state[k.y]);if(state.calendarVisible)clampPosition('calendar',0,state[k.cal])}draw(0)});window.pilot={getState:()=>({...state}),draw,setTheme,artworkFor};render();$('themeStatus').textContent=savedWarning||themeMessage||('目前：'+themeCatalog[state.theme].name+(reviewMode?'（固定對稿狀態，不保存）。':'（可切換）。'));requestAnimationFrame(animate);
